async function request<T>(path: string, init?: RequestInit): Promise<T> {
  const response = await fetch(`${API}${path}`, { ...init, headers: { "Content-Type": "application/json", Authorization: `Bearer ${getAccessToken() ?? ""}`, ...init?.headers } });
  const json = await response.json().catch(() => null);
  if (!response.ok) { const cause = new Error(financeApiMessage(json?.error?.code, json?.error?.message ?? "Unable to complete the finance request.")) as ApiErrorShape; cause.code = json?.error?.code; cause.status = response.status; throw cause; }
  return json;
}

