function Field({ label, help, ...props }: { label: string; help?: string } & React.InputHTMLAttributes<HTMLInputElement>) { return <label className="block text-sm font-semibold">{label}<input {...props} className="mt-1 w-full rounded-xl border bg-white px-3 py-2.5 font-normal dark:bg-slate-950 disabled:bg-slate-100"/>{help && <span className="mt-1 block text-xs font-normal text-slate-500">{help}</span>}</label>; }
function SelectField({ label, options, ...props }: { label: string; options: [string, string][] } & React.SelectHTMLAttributes<HTMLSelectElement>) { return <label className="block text-sm font-semibold">{label}<select {...props} className="mt-1 w-full rounded-xl border bg-white px-3 py-2.5 font-normal dark:bg-slate-950 disabled:bg-slate-100">{options.map(([value, text]) => <option key={value} value={value}>{text}</option>)}</select></label>; }
function Pagination({ meta, onPage }: { meta: PageMeta; onPage: (page: number) => void }) { return <footer className="mt-3 flex flex-wrap items-center justify-between gap-3 rounded-xl border bg-white px-4 py-3 text-sm"><span>Page {meta.page} of {meta.totalPages} · {meta.total} total records</span><span className="flex gap-2"><button type="button" disabled={meta.page <= 1} onClick={() => onPage(meta.page - 1)} className="rounded-lg border px-3 py-1.5 disabled:opacity-40">Previous</button><button type="button" disabled={meta.page >= meta.totalPages} onClick={() => onPage(meta.page + 1)} className="rounded-lg border px-3 py-1.5 disabled:opacity-40">Next</button></span></footer>; }
